SELECT a.*, COALESCE(u.real_name, u.username) as author_name FROM content_article a LEFT JOIN tcm_user u ON a.author_id = u.id WHERE a.status = 1
AND a.category = #{category}
AND (a.constitution_type LIKE CONCAT('%', #{constitutionType}, '%') OR a.constitution_type = 'ALL')
AND (
a.tags LIKE CONCAT('%', #{tag}, '%')
)
AND a.is_featured = #{isFeatured}
ORDER BY a.is_featured DESC, (COALESCE(a.comment_count, 0) + COALESCE(a.favorite_count, 0) + COALESCE(a.like_count, 0) + COALESCE(a.view_count, 0)) DESC, COALESCE(a.comment_count, 0) DESC, COALESCE(a.favorite_count, 0) DESC, COALESCE(a.like_count, 0) DESC, COALESCE(a.view_count, 0) DESC, a.is_top DESC, a.publish_time DESC

SELECT a.*, COALESCE(u.real_name, u.username) as author_name
FROM content_article a
LEFT JOIN tcm_user u ON a.author_id = u.id


        AND a.status = #{status}


        AND a.category = #{category}


        AND (a.constitution_type LIKE CONCAT('%', #{constitutionType}, '%') OR a.constitution_type = 'ALL')


        AND (

            EXISTS (
                SELECT 1 FROM content_article_tag at
                WHERE at.article_id = a.id AND at.tag_name = #{tag}
            )

        )


        AND a.is_featured = #{isFeatured}


        AND (
            a.title LIKE CONCAT('%', #{keyword}, '%')
            OR a.summary LIKE CONCAT('%', #{keyword}, '%')
            OR EXISTS (
                SELECT 1 FROM content_article_tag at
                WHERE at.article_id = a.id AND at.tag_name LIKE CONCAT('%', #{keyword}, '%')
            )
        )


ORDER BY
    a.is_featured DESC,
    a.is_top DESC,
    a.publish_time DESC,
    a.created_at DESC

